//! Shared credit identifies the version of the generator that emitted HTML.
pub(super) const HTML: &str = concat!(
    "Generated by <a href=\"https://ekgf.github.io/grapharch/\">Grapharch ",
    env!("GRAPHARCH_BUILD_LABEL"),
    "</a><span class=\"generator-build\" data-build-channel=\"",
    env!("GRAPHARCH_BUILD_CHANNEL"),
    "\" data-generator-revision=\"",
    env!("GRAPHARCH_GENERATOR_REVISION"),
    "\"></span>"
);
